    /**
     * 构建倒排索引：分词关键词 -> 包含该关键词的原始词条列表
     */
    private static Map<String, List<String>> buildIndex(String text) {
        String[] entries = text.split("\\^");
        JiebaSegmenter segmenter = new JiebaSegmenter();
        Map<String, List<String>> index = new HashMap<>();
        for (String entry : entries) {
            List<SegToken> tokens = segmenter.process(entry, JiebaSegmenter.SegMode.SEARCH);
            for (SegToken token : tokens) {
                String keyword = token.word.trim();
                if (keyword.length() >= 2) {
                    index.computeIfAbsent(keyword, k -> new ArrayList<>()).add(entry);
                }
            }
            // key 值中增加原值，即 value 和 key 一样
            index.computeIfAbsent(entry, k -> new ArrayList<>()).add(entry);
        }
        return index;
    }

    private static List<String> mathByName(List<String> names, Map<String, List<String>> index) {
        Set<String> set = new HashSet<>();
        for (String name : names) {
            for (String key : index.keySet()) {
                if (name.contains(key)) {
                    set.addAll(index.get(key));
                    System.out.println(key + "---" + index.get(key));
                }
            }
        }
        return new ArrayList<>(set);
    }


